const KEY="roxonic_invoice_full_v2";
const $=id=>document.getElementById(id);
const esc=v=>String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));
const today=()=>new Date().toISOString().slice(0,10);
const APP_LOGO_DATA="data:image/png;base64,";

const defaults={
 settings:{businessName:"Your Business Name",phone:"",email:"",website:"",gstin:"",pan:"",address:"Your business address",bankName:"",accountName:"",accountNumber:"",ifsc:"",upiId:"",logo:"",template:"professional",color:"#2563eb",currency:"₹",prefix:"INV",next:1,tax:18,taxMode:"gst"},
 invoices:[],customers:[],products:[],
 about:{name:"Team Roxonic",company:"",role:"",email:"",website:"https://roxoniclimited.com",location:"",bio:""}
};
let data=load();
let items=[{description:"",qty:1,rate:0,tax:data.settings.tax,discount:0}];
let editingCustomerId=null;
let lastSavedInvoice=null;

function load(){try{const saved=JSON.parse(localStorage.getItem(KEY)||"null");if(!saved)return structuredClone(defaults);return {...structuredClone(defaults),...saved,settings:{...structuredClone(defaults.settings),...(saved.settings||{})},about:{...structuredClone(defaults.about),...(saved.about||{})}}}catch{return structuredClone(defaults)}}
function save(){localStorage.setItem(KEY,JSON.stringify(data))}
function toast(m){const t=$("toast");t.textContent=m;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2200)}
function money(n){return `${data.settings.currency}${Number(n||0).toLocaleString("en-IN",{minimumFractionDigits:2,maximumFractionDigits:2})}`}
function num(v){return Number(v)||0}
function nextNo(){return `${data.settings.prefix}-${String(data.settings.next).padStart(6,"0")}`}
function calc(){
 const sub=items.reduce((s,i)=>s+num(i.qty)*num(i.rate),0);
 const itemDisc=items.reduce((s,i)=>s+num(i.discount),0);
 const invDisc=num($("inv-discount")?.value);
 const taxable=Math.max(0,sub-itemDisc-invDisc);
 const rawTax=items.reduce((s,i)=>{
   const base=Math.max(0,num(i.qty)*num(i.rate)-num(i.discount));
   return s+base*num(i.tax)/100;
 },0);
 const ratio=sub>0?rawTax/sub:data.settings.tax/100;
 const finalTax=data.settings._invoiceTaxMode==="none"?0:taxable*ratio;
 let cgst=0,sgst=0;
 const mode=data.settings._invoiceTaxMode||"gst";
 if(mode==="gst"){cgst=finalTax/2;sgst=finalTax/2}
 if(mode==="cgst"){cgst=finalTax}
 if(mode==="sgst"){sgst=finalTax}
 const total=taxable+finalTax,paid=Math.min(total,Math.max(0,num($("inv-paid")?.value)));
 return {sub,itemDisc,invDisc,taxable,tax:finalTax,cgst,sgst,total,paid,due:Math.max(0,total-paid)}
}
function show(page){
 document.querySelectorAll(".page").forEach(x=>x.classList.remove("active"));
 $(page+"-page")?.classList.add("active");
 document.querySelectorAll(".nav").forEach(x=>x.classList.toggle("active",x.dataset.page===page));
 const titles={dashboard:["Dashboard","Fast, private, offline invoicing."],invoice:["New Invoice","Create and share a professional invoice."],invoices:["Invoices","Your complete local invoice history."],customers:["Customers","Customer vault and quick selection."],products:["Products & Services","Reusable products and service rates."],designer:["Invoice Designer","Customize your invoice identity."],business:["Business Profile","Logo, tax, payment and business details."],settings:["Settings","Local application preferences."],about:["About Developer","Information about the developer and product."]};
 $("page-title").textContent=titles[page][0];$("page-subtitle").textContent=titles[page][1];
 if(page==="dashboard") dashboard(); if(page==="invoice") prepareInvoice(); if(page==="invoices") history(); if(page==="customers") customers(); if(page==="products") products(); if(page==="business") loadBusiness(); if(page==="designer") loadDesign(); if(page==="about") loadAbout();
}
function dashboard(){
 const total=data.invoices.reduce((s,x)=>s+x.total,0),paid=data.invoices.reduce((s,x)=>s+x.paid,0);
 $("s-count").textContent=data.invoices.length;$("s-total").textContent=money(total);$("s-paid").textContent=money(paid);$("s-due").textContent=money(total-paid);
 $("side-business").textContent=data.settings.businessName||"Your Business";
 $("latest").innerHTML=data.invoices.slice(0,5).map(x=>`<div class="latest-row"><div><b>${esc(x.invoiceNo)}</b><small>${esc(x.customerName)} • ${esc(x.date)}</small></div><strong>${money(x.total)}</strong></div>`).join("")||`<div class="empty">No invoices yet.</div>`;
}
function prepareInvoice(){
 data.settings._invoiceTaxMode=data.settings.taxMode||"gst";
 if($("tax-mode"))$("tax-mode").value=data.settings._invoiceTaxMode;
 $("inv-no").value=nextNo();
 $("inv-date").value=today();
 $("inv-discount").value=0;$("inv-paid").value=0;
 $("inv-payment").value="Cash";$("inv-notes").value="Thank you for your business.";$("inv-terms").value="Goods once sold are subject to the terms agreed at the time of sale.";
 $("c-name").value="";$("c-phone").value="";$("c-gstin").value="";$("c-address").value="";$("customer-select").value="";
 items=[{description:"",qty:1,rate:0,tax:data.settings.tax,discount:0}];
 fillCustomerSelect(); $("product-list").innerHTML=data.products.map(p=>`<option value="${esc(p.name)}">${esc(p.name)} • ${money(p.rate)}</option>`).join("");
 renderItems(); renderPaper();
}
function fillCustomerSelect(){
 const sel=$("customer-select"), old=sel.value;
 sel.innerHTML=`<option value="">— Select customer —</option>`+data.customers.map(c=>`<option value="${c.id}">${esc(c.name)}${c.phone?" • "+esc(c.phone):""}</option>`).join("");
 if(old)sel.value=old;
}
function renderItems(){
 // IMPORTANT: no full rerender while typing; this is only called when adding/removing items or loading.
 $("items-body").innerHTML=items.map((i,idx)=>`<tr data-row="${idx}">
 <td><input data-field="description" value="${esc(i.description)}" placeholder="Product / service"></td>
 <td><input data-field="qty" type="number" min="0" value="${i.qty}"></td>
 <td><input data-field="rate" type="number" min="0" value="${i.rate}"></td>
 <td><input data-field="tax" type="number" min="0" value="${i.tax}"></td>
 <td><input data-field="discount" type="number" min="0" value="${i.discount}"></td>
 <td class="row-amount">${money(num(i.qty)*num(i.rate)-num(i.discount))}</td>
 <td><button class="remove" data-remove="${idx}">×</button></td></tr>`).join("");
}
function renderPaper(){
 const s=data.settings,c=calc(), mode=s._invoiceTaxMode||"gst";
 const cust={name:$("c-name").value||"Customer Name",phone:$("c-phone").value,gstin:$("c-gstin").value,address:$("c-address").value};
 const logo=s.logo?`<img class="p-logo" src="${s.logo}" alt="Business logo">`:`<img class="p-logo" src="${APP_LOGO_DATA}" alt="Roxonic Invoice logo">`;
 const billOfSupply=mode==="none";
 const taxHeader=billOfSupply?"":`<th>Tax</th>`;
 const taxRows=billOfSupply?"":`${mode==="gst"||mode==="cgst"?`<div><span>CGST</span><b>${money(c.cgst)}</b></div>`:""}${mode==="gst"||mode==="sgst"?`<div><span>SGST</span><b>${money(c.sgst)}</b></div>`:""}`;
 const itemRows=items.map(i=>`<tr><td>${esc(i.description||"Item")}</td><td>${i.qty}</td><td>${money(i.rate)}</td>${billOfSupply?"":`<td>${num(i.tax)}%</td>`}<td>${money(num(i.qty)*num(i.rate)-num(i.discount))}</td></tr>`).join("");
 $("paper").style.setProperty("--pc",s.color);
 $("paper").innerHTML=`<div class="p-head"><div class="p-brand">${logo}<div><h2>${esc(s.businessName)}</h2><p>${esc(s.address)}</p><p>${esc([s.phone,s.email].filter(Boolean).join(" • "))}</p>${s.gstin?`<p>GSTIN: ${esc(s.gstin)}</p>`:""}</div></div><div class="p-meta"><h1>${billOfSupply?"BILL OF SUPPLY":"TAX INVOICE"}</h1><p><b>${esc($("inv-no").value)}</b></p><p>${esc($("inv-date").value)}</p><p class="tax-mode-label">${billOfSupply?"Supply without tax":mode==="gst"?"GST • CGST + SGST":mode==="cgst"?"Tax • CGST only":"Tax • SGST only"}</p></div></div>
 <div class="bill"><label>BILL TO</label><b>${esc(cust.name)}</b><p>${esc(cust.address)}</p><p>${esc([cust.phone,cust.gstin?"GSTIN: "+cust.gstin:""].filter(Boolean).join(" • "))}</p></div>
 <table class="p-items"><thead><tr><th>Description</th><th>Qty</th><th>Rate</th>${taxHeader}<th>Amount</th></tr></thead><tbody>${itemRows}</tbody></table>
 <div class="totals"><div><span>Subtotal</span><b>${money(c.sub)}</b></div><div><span>Discount</span><b>-${money(c.itemDisc+c.invDisc)}</b></div><div><span>Taxable</span><b>${money(c.taxable)}</b></div>${taxRows}<div class="grand"><span>Total</span><b>${money(c.total)}</b></div><div><span>Paid</span><b>${money(c.paid)}</b></div><div><span>Balance Due</span><b>${money(c.due)}</b></div></div>
 <div class="p-notes"><b>Notes</b><div>${esc($("inv-notes").value)}</div><b>Terms & Conditions</b><div>${esc($("inv-terms").value)}</div>${s.upiId?`<b>UPI</b><div>${esc(s.upiId)}</div>`:""}</div><div class="p-foot">Thank you for your business • ${esc(s.businessName)}</div>`;
}
function saveInvoice(){
 if(!$("c-name").value.trim())return toast("Select or enter a customer.");
 if(!items.some(i=>i.description.trim()))return toast("Add an item description.");
 const c=calc(),inv={id:Date.now(),invoiceNo:$("inv-no").value,date:$("inv-date").value,taxMode:data.settings._invoiceTaxMode||"gst",customerName:$("c-name").value.trim(),phone:$("c-phone").value,gstin:$("c-gstin").value,address:$("c-address").value,items:structuredClone(items),...c,paid:c.paid,status:c.paid>=c.total?"Paid":c.paid>0?"Partial":"Unpaid",payment:$("inv-payment").value,notes:$("inv-notes").value,terms:$("inv-terms").value};
 data.invoices.unshift(inv);data.settings.next=num(data.settings.next)+1;
 const existing=data.customers.find(x=>x.name.toLowerCase()===inv.customerName.toLowerCase());
 if(existing){existing.phone=inv.phone;existing.gstin=inv.gstin;existing.address=inv.address}
 else data.customers.push({id:Date.now()+1,name:inv.customerName,phone:inv.phone,email:"",gstin:inv.gstin,address:inv.address});
 save();lastSavedInvoice=inv;dashboard();openSavedModal(inv);resetInvoice();
}
function openSavedModal(inv){
 $("saved-summary").textContent=`${inv.invoiceNo} • ${inv.customerName} • ${money(inv.total)} • ${inv.status}`;
 $("saved-modal").classList.add("show");
}
function resetInvoice(){data.settings._invoiceTaxMode=data.settings.taxMode||"gst";items=[{description:"",qty:1,rate:0,tax:data.settings.tax,discount:0}];$("c-name").value="";$("c-phone").value="";$("c-gstin").value="";$("c-address").value="";$("inv-paid").value=0;prepareInvoice()}

async function printSaved(){
 if(!lastSavedInvoice)return;
 const current=lastSavedInvoice;
 await loadInvoiceIntoPreview(current,false);
 await window.roxonic.print();
}
async function pdfSaved(){
 if(!lastSavedInvoice)return;
 const current=lastSavedInvoice;
 await loadInvoiceIntoPreview(current,false);
 const r=await window.roxonic.exportPDF({invoiceHtml:$("paper").innerHTML,customerName:$("c-name").value||"Customer",invoiceNo:$("inv-no").value});
 if(r?.ok)toast("PDF downloaded successfully.");
}
async function loadInvoiceIntoPreview(inv,showPage=true){
 if(showPage)show("invoice");
 $("inv-no").value=inv.invoiceNo;$("inv-date").value=inv.date;$("tax-mode").value=inv.taxMode||"gst";data.settings._invoiceTaxMode=$("tax-mode").value;$("c-name").value=inv.customerName;$("c-phone").value=inv.phone||"";$("c-gstin").value=inv.gstin||"";$("c-address").value=inv.address||"";$("inv-paid").value=inv.paid||0;$("inv-payment").value=inv.payment||"Cash";$("inv-notes").value=inv.notes||"";$("inv-terms").value=inv.terms||"";items=structuredClone(inv.items||[]);renderItems();renderPaper();
}

function history(){
 const q=($("invoice-search")?.value||"").toLowerCase();
 const list=data.invoices.filter(x=>`${x.invoiceNo} ${x.customerName} ${x.phone}`.toLowerCase().includes(q));
 $("history").innerHTML=list.map(x=>`<tr><td><b>${esc(x.invoiceNo)}</b></td><td>${esc(x.customerName)}</td><td>${esc(x.date)}</td><td>${money(x.total)}</td><td>${money(x.paid)}</td><td>${money(x.due)}</td><td><span class="chip">${x.status}</span></td><td><button class="btn small" data-reuse="${x.id}">Reuse</button></td></tr>`).join("");
 $("history-empty").style.display=list.length?"none":"block";
}
function customers(){
 $("customers").innerHTML=data.customers.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.phone)}</td><td>${esc(c.email)}</td><td>${esc(c.gstin)}</td><td>${esc(c.address)}</td><td><button class="btn small" data-edit-c="${c.id}">Edit</button> <button class="btn small" data-del-c="${c.id}">Delete</button></td></tr>`).join("");
 $("customers-empty").style.display=data.customers.length?"none":"block";
}
function products(){
 $("products").innerHTML=data.products.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.sku)}</td><td>${money(p.rate)}</td><td>${p.tax}%</td><td><button class="btn small" data-del-p="${p.id}">Delete</button></td></tr>`).join("");
 $("products-empty").style.display=data.products.length?"none":"block";
}
function loadBusiness(){
 const s=data.settings; const map={"b-name":"businessName","b-phone":"phone","b-email":"email","b-web":"website","b-gstin":"gstin","b-pan":"pan","b-address":"address","b-bank":"bankName","b-account-name":"accountName","b-account":"accountNumber","b-ifsc":"ifsc","b-upi":"upiId"};
 for(const [id,k] of Object.entries(map))$(id).value=s[k]||"";
 $("logo-preview").innerHTML=s.logo?`<img src="${s.logo}">`:`<img src="${APP_LOGO_DATA}">`;
}
function loadDesign(){
 const s=data.settings; $("d-template").value=s.template;$("d-color").value=s.color;$("d-currency").value=s.currency;$("d-prefix").value=s.prefix;$("d-next").value=s.next;$("d-tax").value=s.tax;$("theme-line").style.background=s.color;
}
function loadAbout(){ /* Official About content is fixed and read-only. */ }

document.querySelectorAll(".nav").forEach(b=>{b.type="button";b.addEventListener("click",e=>{e.preventDefault();show(b.dataset.page);});});
document.addEventListener("click",e=>{const el=e.target.closest("[data-external]");if(el){e.preventDefault();window.roxonic.openExternal(el.dataset.external);}});
document.querySelectorAll("[data-target]").forEach(b=>b.addEventListener("click",e=>{e.preventDefault();show(b.dataset.target)}));
document.addEventListener("click",e=>{const b=e.target.closest("[data-target]");if(b){e.preventDefault();show(b.dataset.target)}});
$("top-new").onclick=e=>{e.preventDefault();show("invoice")};
$("hero-new").onclick=e=>{e.preventDefault();show("invoice")};
document.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="n"){e.preventDefault();show("invoice")}if(e.key==="Escape"&&$("saved-modal")?.classList.contains("show"))$("saved-modal").classList.remove("show")});
$("add-item").onclick=()=>{items.push({description:"",qty:1,rate:0,tax:data.settings.tax,discount:0});renderItems();renderPaper()};
$("items-body").addEventListener("input",e=>{
 const row=e.target.closest("tr"); if(!row)return; const i=num(row.dataset.row),f=e.target.dataset.field;if(!f)return;
 items[i][f]=f==="description"?e.target.value:num(e.target.value);
 if(f==="description"){const p=data.products.find(p=>p.name.toLowerCase()===e.target.value.trim().toLowerCase());if(p){items[i].rate=p.rate;items[i].tax=p.tax;row.querySelector('[data-field="rate"]').value=p.rate;row.querySelector('[data-field="tax"]').value=p.tax;}}
 const amount=row.querySelector(".row-amount");if(amount)amount.textContent=money(num(items[i].qty)*num(items[i].rate)-num(items[i].discount));
 renderPaper();
});
$("items-body").addEventListener("click",e=>{const b=e.target.closest("[data-remove]");if(!b)return;items.splice(num(b.dataset.remove),1);if(!items.length)items.push({description:"",qty:1,rate:0,tax:data.settings.tax,discount:0});renderItems();renderPaper()});
["c-name","c-phone","c-gstin","c-address","inv-date","inv-discount","inv-paid","inv-notes","inv-terms"].forEach(id=>$(id).addEventListener("input",renderPaper));
$("customer-select").onchange=()=>{const c=data.customers.find(x=>String(x.id)===$("customer-select").value);if(c){$("c-name").value=c.name;$("c-phone").value=c.phone;$("c-gstin").value=c.gstin;$("c-address").value=c.address;renderPaper()}};
$("add-customer-inline").onclick=()=>show("customers");
$("save-btn").onclick=saveInvoice;

$("tax-mode").onchange=()=>{
 data.settings._invoiceTaxMode=$("tax-mode").value;
 renderPaper();
};
$("print-btn").onclick=async()=>{await window.roxonic.print();toast("Print dialog opened.")};
$("pdf-btn").onclick=async()=>{const r=await window.roxonic.exportPDF({invoiceHtml:$("paper").innerHTML,customerName:$("c-name").value||"Customer",invoiceNo:$("inv-no").value});if(r?.ok)toast("PDF exported.");};
document.querySelectorAll("[data-share]").forEach(b=>b.onclick=async()=>{
 const c=calc(), text=`Invoice ${$("inv-no").value}%0ACustomer: ${encodeURIComponent($("c-name").value||"Customer")}%0ATotal: ${encodeURIComponent(money(c.total))}%0ABalance: ${encodeURIComponent(money(c.due))}`;
 if(b.dataset.share==="whatsapp")await window.roxonic.openExternal(`https://wa.me/?text=${text}`);
 if(b.dataset.share==="email")await window.roxonic.openExternal(`mailto:?subject=${encodeURIComponent("Invoice "+$("inv-no").value)}&body=${text}`);
 if(b.dataset.share==="copy"){await navigator.clipboard.writeText(decodeURIComponent(text.replaceAll("%0A","\n")));toast("Invoice summary copied.");}
});
$("invoice-search").oninput=history;
$("save-customer").onclick=()=>{
 const name=$("nc-name").value.trim();if(!name)return toast("Enter customer name.");
 const payload={name,phone:$("nc-phone").value,email:$("nc-email").value,gstin:$("nc-gstin").value,address:$("nc-address").value};
 if(editingCustomerId){const c=data.customers.find(x=>x.id===editingCustomerId);Object.assign(c,payload);toast("Customer updated.");}
 else {data.customers.push({id:Date.now(),...payload});toast("Customer added.");}
 editingCustomerId=null;$("save-customer").textContent="Add Customer";$("cancel-customer-edit").style.display="none";
 save();["nc-name","nc-phone","nc-email","nc-gstin","nc-address"].forEach(x=>$(x).value="");customers();fillCustomerSelect();
};
$("cancel-customer-edit").onclick=()=>{editingCustomerId=null;$("save-customer").textContent="Add Customer";$("cancel-customer-edit").style.display="none";["nc-name","nc-phone","nc-email","nc-gstin","nc-address"].forEach(x=>$(x).value="")};
$("save-product").onclick=()=>{const name=$("np-name").value.trim();if(!name)return toast("Enter product name.");data.products.push({id:Date.now(),name,sku:$("np-sku").value,rate:num($("np-rate").value),tax:num($("np-tax").value)});save();["np-name","np-sku","np-rate"].forEach(x=>$(x).value="");$("np-tax").value=18;products();toast("Product added.");};
$("customers").onclick=e=>{
 const edit=e.target.closest("[data-edit-c]");
 if(edit){
   const c=data.customers.find(x=>String(x.id)===edit.dataset.editC);if(!c)return;
   editingCustomerId=c.id;$("nc-name").value=c.name;$("nc-phone").value=c.phone||"";$("nc-email").value=c.email||"";$("nc-gstin").value=c.gstin||"";$("nc-address").value=c.address||"";
   $("save-customer").textContent="Update Customer";$("cancel-customer-edit").style.display="inline-block";show("customers");toast("Editing customer.");
   return;
 }
 const b=e.target.closest("[data-del-c]");if(b){data.customers=data.customers.filter(x=>String(x.id)!==b.dataset.delC);save();customers();fillCustomerSelect()}
};
$("products").onclick=e=>{const b=e.target.closest("[data-del-p]");if(b){data.products=data.products.filter(x=>String(x.id)!==b.dataset.delP);save();products()}};
$("history").onclick=e=>{const b=e.target.closest("[data-reuse]");if(!b)return;const x=data.invoices.find(v=>String(v.id)===b.dataset.reuse);if(!x)return;show("invoice");$("tax-mode").value=x.taxMode||"gst";data.settings._invoiceTaxMode=$("tax-mode").value;$("c-name").value=x.customerName;$("c-phone").value=x.phone;$("c-gstin").value=x.gstin;$("c-address").value=x.address;items=structuredClone(x.items);renderItems();renderPaper();toast("Invoice loaded as a new draft.")};
$("save-design").onclick=()=>{data.settings.template=$("d-template").value;data.settings.color=$("d-color").value;data.settings.currency=$("d-currency").value||"₹";data.settings.prefix=$("d-prefix").value||"INV";data.settings.next=Math.max(1,num($("d-next").value));data.settings.tax=num($("d-tax").value);save();toast("Customization saved.");renderPaper()};
$("choose-logo").onclick=async()=>{const logo=await window.roxonic.chooseLogo();if(logo){data.settings.logo=logo;save();loadBusiness();renderPaper();toast("Business logo added.")}};
$("remove-logo").onclick=()=>{data.settings.logo="";save();loadBusiness();renderPaper();toast("Logo removed.")};
$("save-business").onclick=()=>{const s=data.settings,map={"b-name":"businessName","b-phone":"phone","b-email":"email","b-web":"website","b-gstin":"gstin","b-pan":"pan","b-address":"address","b-bank":"bankName","b-account-name":"accountName","b-account":"accountNumber","b-ifsc":"ifsc","b-upi":"upiId"};for(const [id,k] of Object.entries(map))s[k]=$(id).value;save();$("side-business").textContent=s.businessName||"Your Business";renderPaper();toast("Business profile saved.")};

$("clear-data").onclick=()=>{if(confirm("Delete all local invoices, customers and products?")){data.invoices=[];data.customers=[];data.products=[];save();dashboard();toast("Local data cleared.")}};


$("saved-close").onclick=()=>$("saved-modal").classList.remove("show");
$("saved-print").onclick=printSaved;
$("saved-pdf").onclick=pdfSaved;
$("saved-whatsapp").onclick=async()=>{if(!lastSavedInvoice)return;const x=lastSavedInvoice;await window.roxonic.openExternal(`https://wa.me/?text=${encodeURIComponent(`Invoice ${x.invoiceNo}\nCustomer: ${x.customerName}\nTotal: ${money(x.total)}\nBalance: ${money(x.due)}`)}`)};

loadBusiness();loadDesign();loadAbout();dashboard();prepareInvoice();
